#!/usr/bin/env node
// paths.mjs — the one place that knows where the harness lives on disk.
//
// WHY IT EXISTS. Until the harness was packaged as a plugin, 36 call sites
// across 28 files resolved their own paths against `homedir()/.claude/...`.
// That worked while the harness only ever lived in one place. A plugin is
// copied into a version-keyed cache directory whose path nobody can predict,
// so every one of those call sites would have resolved to a file that is not
// there — silently, since most of them feed `readFileSync` inside a try or a
// region slicer that reports "region not found" rather than "wrong path".
//
// This is the same move `rows.mjs` already made for metrics.jsonl, for the same
// reason: a rule that lives in 28 copies is a rule that will be wrong in at
// least one of them. `replay-region-coverage.mjs` guards that nothing goes back
// to resolving its own.
//
// DATA vs CODE. The plugin directory is replaced wholesale on every update, so
// nothing writable may live inside it. Measurement state resolves to DATA_DIR
// instead, which is outside the plugin and survives updates.

import { existsSync, realpathSync } from "node:fs";
import { homedir } from "node:os";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";
import { cwdRepo, resolveRepo } from "../../../lib/operator.mjs";

const HERE = dirname(fileURLToPath(import.meta.url));

// `CLAUDE_PLUGIN_ROOT` is set when a plugin component runs inside Claude Code.
// The eval battery is also run by hand from a terminal, where it is not set, so
// the relative walk is the fallback rather than the other way round: it is
// derived from this file's own location and cannot be stale.
//   <root>/skills/review-pr/eval/paths.mjs -> ../../.. -> <root>
export const PLUGIN_ROOT =
  process.env.CLAUDE_PLUGIN_ROOT || resolve(HERE, "..", "..", "..");

export const SKILL_DIR = resolve(PLUGIN_ROOT, "skills", "review-pr");
// The commented source is what the battery reads. The Workflow runs the built
// copy, the same code with comment lines removed (scripts/build-workflow.mjs).
export const WORKFLOW = resolve(PLUGIN_ROOT, "workflow-src", "tribunal.js");
export const WORKFLOW_BUILT = resolve(PLUGIN_ROOT, "workflows", "tribunal.js");
export const LIB_DIR = resolve(PLUGIN_ROOT, "lib");
export const AGENTS_DIR = resolve(PLUGIN_ROOT, "agents");

export const lib = (name) => resolve(LIB_DIR, name);
export const agent = (name) => resolve(AGENTS_DIR, name);

// Writable state. Never inside PLUGIN_ROOT — see the DATA vs CODE note above.
export const DATA_DIR =
  process.env.TRIBUNAL_DATA_DIR || resolve(homedir(), ".claude", "tribunal-data");

export const METRICS_PATH = resolve(DATA_DIR, "metrics.jsonl");
export const AGENT_COSTS_PATH = resolve(DATA_DIR, "agent-costs.jsonl");
export const AGENT_COUNTS_PATH = resolve(DATA_DIR, "agent-counts.jsonl");
export const INFLIGHT_PATH = resolve(DATA_DIR, "inflight-runs.jsonl");
export const QUEUE_STATE_PATH = resolve(DATA_DIR, "queue-state.json");

// A client's recorded history and test data: the runs the replays re-decide,
// the fixtures cut from real runs, the labelled corpus, the specs and the
// release log. It lives in the documentation repo next to plugins/, never
// inside a plugin, so installing the plugin never copies a client's data.
// Outside that repo these paths do not exist, and every replay that needs one
// fails on the missing file instead of passing over nothing.
export const HARNESS_DATA =
  process.env.TRIBUNAL_HARNESS_DATA || resolve(PLUGIN_ROOT, "..", "..", "review-harness-data");
export const TRIBUNAL_DATA = resolve(HARNESS_DATA, "tribunal");
export const FIXTURES_DIR = resolve(TRIBUNAL_DATA, "fixtures");
export const CORPUS_DIR = resolve(TRIBUNAL_DATA, "corpus");
// The release log is this repository's own, generic: a row says which gate ran
// and what changed, and carries no client data. TRIBUNAL_RELEASES overrides it.
export const RELEASES_PATH = process.env.TRIBUNAL_RELEASES || resolve(PLUGIN_ROOT, "RELEASES.md");
// The replays that read HARNESS_DATA and so cannot run where it is absent. One
// list for the whole repo, kept by scripts/check-portable.sh.
export const NEEDS_DATA_PATH = resolve(PLUGIN_ROOT, "scripts", "needs-data.txt");
export const PROFILES_DIR = resolve(HARNESS_DATA, "profiles");
// A frozen ledger, so a replay re-decides the same recorded runs on every
// machine instead of whatever this operator's DATA_DIR happens to hold.
export const RECORDED_METRICS_PATH = resolve(TRIBUNAL_DATA, "ledger", "metrics.jsonl");
export const RECORDED_INFLIGHT_PATH = resolve(TRIBUNAL_DATA, "ledger", "inflight-runs.jsonl");

// Claude Code's own session transcripts. Genuinely outside the plugin, and
// genuinely under the real home directory — this one is not a packaging
// artefact and stays homedir-based.
export const PROJECTS_DIR = resolve(homedir(), ".claude", "projects");

// The per-workspace transcript directory. Was hardcoded to one contributor's
// path in six files, which made every cost analysis silently empty on anyone
// else's machine — `findRunDirs` on a missing directory returns nothing, so the
// failure reads as "this run had no agents" rather than as a wrong path.
export function projectDir(cwd = process.cwd()) {
  if (process.env.TRIBUNAL_PROJECT_DIR) return process.env.TRIBUNAL_PROJECT_DIR;
  return resolve(PROJECTS_DIR, projectSlug(resolve(cwd)));
}

// Claude Code's own rule: every character but a letter or a digit becomes "-".
// Replacing only "/", "." and "_" left a Windows cwd (C:\GIT\x) whole, and
// resolve() then returned the cwd itself instead of a directory under projects.
export function projectSlug(absPath) {
  return absPath.replace(/[^A-Za-z0-9]/g, "-");
}

// The repository under review, as a checkout on disk. Only the Tier-1 rigs
// need one (they re-read the code a recorded refuter read). TRIBUNAL_REPO_DIR
// wins; otherwise the repo is `repo`, else what a review would pick (the
// operator's defaultRepo, else the cwd's origin), and the checkout is the first
// of the cwd, ./<name> and ../<name> whose origin is exactly that repo. Null rather than a guess when none matches: a wrong
// checkout would score an arm against the wrong source.
export function reviewRepo(repo = "", { cwd = process.cwd(), originOf = cwdRepo } = {}) {
  if (process.env.TRIBUNAL_REPO_DIR) return process.env.TRIBUNAL_REPO_DIR;
  const target = repo || resolveRepo({ cwd, cwdRepoOf: originOf }).repo;
  if (!target) return null;
  const name = target.split("/")[1];
  for (const dir of [cwd, resolve(cwd, name), resolve(cwd, "..", name)])
    if (existsSync(dir) && originOf(dir) === target) return dir;
  return null;
}

// Is this module the entry point? Callers pass their own `import.meta.url`:
//
//   if (isMainModule(import.meta.url)) { ... }
//
// The obvious spelling, `import.meta.url === "file://" + process.argv[1]`, is
// wrong twice over, and both failures are silent — the guard is false, the body
// never runs, and the process exits 0, which is indistinguishable from a script
// that ran and found nothing.
//
//   - Through a symlink (the ~/.claude/skills/... link into this plugin's real,
//     version-keyed cache directory), argv[1] keeps the link path while
//     import.meta.url resolves to the real one.
//   - On Windows it can never match at all: import.meta.url normalises to
//     `file:///C:/Users/...` (three slashes, forward slashes) while the string
//     concatenation builds `file://C:\Users\...`. Measured 2026-08-10 — seven
//     eval scripts, `lost-runs.mjs` among them, had never executed on that
//     platform. A loss detector reporting silence over 44 started / 38 completed
//     runs is the failure this guard is supposed to make impossible.
//
// Resolving both sides to a real path fixes both. All NINE scripts under
// `scripts/` carry this as a local copy predating this one — `build-post-footer`,
// `count-in-context-agents`, `harness-version`, `incremental-scope`,
// `locate-last-row`, `persist-review-record`, `post-review`,
// `resolve-evidence-line`, `strip-draft-comments`. They are equivalent, and this
// is the shared version for the same reason the rest of this file exists. The
// count is the argument, so it is spelled as a list: nine copies is a rule that
// will be wrong in at least one of them, and "four" understated the case by more
// than half.
export function isMainModule(importMetaUrl) {
  try {
    return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(importMetaUrl));
  } catch {
    return false;
  }
}

scripts.skills/review-pr/scripts/harness-version:
#!/usr/bin/env node
// harness-version.mjs — a content hash identifying WHICH version of the
// peer-review harness produced a given run. Deterministic, 0 tokens, no git
// required (it works before, during and after the repo exists).
//
// Why. metrics.jsonl holds 44 rows produced by an unknown number of code
// versions, with nothing on the row saying which. That single gap is why "are we
// better or worse than before" cannot be answered from the data we already paid
// to collect: every comparison silently mixes versions. `schemaVersion` does not
// substitute — it describes the row's SHAPE, not the code that filled it.
//
// The hash covers only files that can change a review's BEHAVIOUR. Measurement
// data (metrics.jsonl, agent-*.jsonl), specs and the eval corpus are excluded on
// purpose: they change constantly and their movement is not a new harness. The
// eval scripts are excluded for the same reason — a replay is a test of the
// harness, not a part of it.
//
// Usage:
//   node scripts/harness-version.mjs             # id + file count
//   node scripts/harness-version.mjs --short     # just the id, for stamping
//   node scripts/harness-version.mjs --manifest  # every path with its own hash
//
// A missing file is a HARD failure, not a skipped line: silently hashing 11 of
// 12 files would produce a stable-looking id for a harness that lost a piece.

import { createHash } from "node:crypto";
import { existsSync, readFileSync, readdirSync, realpathSync } from "node:fs";
import { join } from "node:path";
import { fileURLToPath } from "node:url";
import { PLUGIN_ROOT } from "../eval/paths.mjs";

// A strict `import.meta.url === file://${process.argv[1]}` comparison breaks
// when the script is invoked through a symlink (e.g. the ~/.claude/skills/...
// symlink into this plugin's real, version-keyed cache directory): argv[1]
// keeps the symlink path while import.meta.url resolves to the real one, so
// they never match, main() silently never runs, and the script exits 0 having
// done nothing. Resolve both sides to their real path before comparing.
function isMainModule() {
  try {
    return realpathSync(process.argv[1]) === realpathSync(fileURLToPath(import.meta.url));
  } catch {
    return false;
  }
}

// Was `resolve(homedir(), ".claude")` until the harness became a plugin. A
// plugin is copied into a version-keyed cache directory, so a hash anchored to
// the home directory would have hashed whatever older copy still sat in
// ~/.claude — or thrown on a machine that never had one.
const ROOT = PLUGIN_ROOT;

// THE SURFACE — defined once here and imported by eval/release.mjs, so a freeze
// and a version id can never disagree about what the harness is.
// THE SURFACE — defined once here and imported by eval/release.mjs, so a freeze
// and a version id can never disagree about what the harness is.
//
// `lib/` and `workflows/` are DIRECTORIES, not a hand-kept list of names, since
// 2026-09-09. They were a list, and a list fails in the direction that costs
// you: a module added to lib/ was outside the freeze until somebody remembered
// to name it, and nothing said otherwise. Two had already fallen through.
// `lib/verified.mjs` is the evidence gate that demotes blocking findings and was
// never listed at all; `lib/resolve-verified-anchors.mjs` shipped in v52 and
// `workflows/harness-selfcheck.js` moved into the plugin in v54, and neither was
// added. So a file under these directories is in the freeze unless someone
// writes down why it is not, which is the direction that fails safe.
export const SURFACE = ["skills/review-pr/SKILL.md"];

// Deliberately outside the freeze, with the reason. Empty today, and the entry
// shape is the point: eval/replay-surface-coverage.mjs refuses an exclusion with
// no reason and refuses one naming a file that no longer exists, so this cannot
// become a place to quietly park things.
export const SURFACE_EXCLUDED = {};

// Directories whose every matching file counts, sorted for determinism.
const SURFACE_DIRS = [
  { dir: "skills/review-pr/references", exts: [".md"] },
  { dir: "skills/review-pr/scripts", exts: [".mjs"] },
  // The orchestrator and the self-check that audits it. Both are executed by
  // the Workflow runtime; a change to either changes what a run does.
  { dir: "workflows", exts: [".js"] },
  // Every module and script the harness shells out to or imports at run time.
  { dir: "lib", exts: [".mjs", ".sh"] },
  // The agent definitions the harness dispatches into. Excluded until
  // 2026-07-27, which meant a frozen version did not freeze the 240-line prompt
  // that shapes every lens, the bot vetting, the completeness critic and the
  // prior-finding verifier — editing it changed every review with no version
  // bump. A hash over "the behavioural surface" that omits the most influential
  // prompt in the harness is not a hash over the behavioural surface. That
  // sentence is why lib/ and workflows/ became directories too.
  //
  // `code-review-expert.md` used to be a SYMLINK into the BE repo, which meant a
  // checkout of any tag restored a dangling link on a machine without that repo
  // at that path. Packaging the harness as a plugin vendored a real copy here,
  // so the hash now covers bytes this repository can actually restore. The cost
  // is that the same definition is versioned in two repositories on different
  // branch cadences, and nothing yet detects them drifting apart.
  { dir: "agents", exts: [".md"] },
  // The methodology the lens personas Read before every review
  // (agents/code-review-expert.md). Outside the hash until 2026-10-19: appending
  // a rule to code-review-methodology.md changed every review and left the id
  // unchanged. A project profile is NOT hashed here; a run records its
  // profileSha256 separately, so the harness id stays comparable across projects.
  { dir: "methodology", exts: [".md"] },
];

// The battery is hashed SEPARATELY, and the separation is the point.
//
// A freeze row asserts "the offline battery was green at this content hash", and
// until now the hash did not pin the battery: `eval/` was outside the surface,
// so `pr-harness-4af7ff70ff8e` is the same id `main` carried while
// `replay-embedded-bash` was red. The row's central claim could not be
// re-verified by checking out its own hash.
//
// The fix is not to fold `eval/` into the surface. `harnessVersion` is the field
// that makes any comparison BETWEEN runs meaningful, and a test-only edit that
// moved it would put churn into exactly the field that must not have any: two
// runs would carry different ids while behaving identically. So the battery gets
// its own id, and a freeze row records both. The claim it can then make is "the
// battery at hash B was green over the harness at hash H", which is checkable.
//
// Everything under eval/ counts, fixtures and corpus included. A battery result
// over different fixtures is a different result, and unlike the harness hash
// this one has no cross-run comparison to protect, so completeness beats
// stability here.
const BATTERY_DIR = "skills/review-pr/eval";

function filesUnder(dir, exts) {
  const abs = join(ROOT, dir);
  if (!existsSync(abs)) throw new Error(`harness surface directory missing: ${dir}`);
  const out = [];
  for (const entry of readdirSync(abs, { withFileTypes: true })) {
    const rel = `${dir}/${entry.name}`;
    if (entry.isDirectory()) out.push(...filesUnder(rel, exts));
    else if (!exts || exts.some((e) => entry.name.endsWith(e))) out.push(rel);
  }
  return out;
}

function digest(paths) {
  const entries = paths.sort().map((rel) => {
    const abs = join(ROOT, rel);
    if (!existsSync(abs)) throw new Error(`harness surface file missing: ${rel}`);
    return { path: rel, sha: createHash("sha256").update(readFileSync(abs)).digest("hex") };
  });
  // Hash the MANIFEST TEXT, not the concatenated contents: two files swapping
  // their contents would collide under concatenation and not under this.
  const manifest = entries.map((e) => `${e.path}:${e.sha}`).join("\n");
  return { entries, manifest, short: createHash("sha256").update(manifest).digest("hex").slice(0, 12) };
}

export function surfaceFiles() {
  const fromDirs = SURFACE_DIRS.flatMap(({ dir, exts }) => filesUnder(dir, exts));
  return [...SURFACE, ...fromDirs].filter((f) => !(f in SURFACE_EXCLUDED)).sort();
}

// Every file the battery hash covers. Exported so the coverage replay and any
// future consumer read the same definition this module uses.
export function batteryFiles() {
  return filesUnder(BATTERY_DIR, null).sort();
}

export function batteryVersion() {
  const { entries, manifest, short } = digest(batteryFiles());
  return { id: `pr-battery-${short}`, entries, manifest };
}

export function harnessVersion() {
  const { entries, manifest, short } = digest(surfaceFiles());
  return { id: `pr-harness-${short}`, entries, manifest };
}

if (isMainModule()) {
  const { id, entries } = harnessVersion();
  if (process.argv.includes("--short")) {
    console.log(id);
  } else if (process.argv.includes("--manifest")) {
    console.log(id);
    for (const e of entries) console.log(`  ${e.sha.slice(0, 12)}  ${e.path}`);
  } else {
    console.log(`${id}  (${entries.length} files)`);
  }
}
